import type { RawAppInfo } from "../../src/mappers/app.js";
import type { MappedWindow } from "../../src/types.js";

export const APPS_DIR = "/home/user/.local/share/applications";
export const GENERATED_DIR = `${APPS_DIR}/icons-matched`;

const steamGame = (name: string, gameId: string): RawAppInfo => ({
  id: `${name}.desktop`,
  name,
  commandline: `steam steam://rungameid/${gameId}`,
  icon: `steam_icon_${gameId}`,
  filename: `${APPS_DIR}/${name}.desktop`,
});

const systemApp = (
  id: string,
  name: string,
  commandline: string,
  icon = id.replace(/\.desktop$/, ""),
): RawAppInfo => ({
  id,
  name,
  commandline,
  icon,
  filename: `/usr/share/applications/${id}`,
});

